class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def KDistanceNodes(root, target, k):
    def find_path(node, target, path):
        if node is None:
            return False
        path.append(node.val)
        if node.val == target:
            return True
        if (node.left and find_path(node.left, target, path)) or (node.right and find_path(node.right, target, path)):
            return True
        path.pop()
        return False

    def printk_distance_node(node, k, path, result):
        if node is None or k < 0:
            return
        if k == 0:
            result.append(node.val)
            return
        if node.left and node.left.val not in path:
            printk_distance_node(node.left, k - 1, path, result)
        if node.right and node.right.val not in path:
            printk_distance_node(node.right, k - 1, path, result)

    path = []
    find_path(root, target, path)
    result = []
    for i in range(len(path)):
        if i == k:
            result.append(path[i])
        else:
            printk_distance_node(root, k - i - 1, path[:i], result)
    return sorted(result)

